/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.imports
 */
function evaluateProperty({
    api,
    imports
}) {
    let currentCount;
    let percentage;
    const localeOutput = api.data.analytics_user_locale_get_list.output;

    if (api.data.users_count.output) {
        percentage = api.data.users_count.output.percentage || null;
    }

    if (api.data.users_count.output) {
        currentCount = api.data.users_count.output.currentCountFormatted || null;
    }

    return `${currentCount ? `${currentCount} ${localeOutput.results}` : ''} ${percentage ? `(${(percentage * 100).toFixed(0)}%)` : ''}`;
}

